resposta:
O robô não abria ordens por alguns motivos que identifiquei no seu código:

1. **Detecção de rompimento durante a formação da vela** — você comparava `iHigh(...,0)` e `iClose(...,0)` a cada tick, enquanto a vela ainda estava sendo desenhada. Isso fazia os sinais quase nunca se completarem (o rompimento "só aparecia" no fim, e o close parcial às vezes enganava).
2. **Ausência de checagem de ordens abertas** — sem verificar se já havia ordem ativa do mesmo lado, era possível tentar mandar ordens duplicadas (e falhas silenciosas).
3. **Bug no Trailing Stop** — a lógica antiga apertava o stop imediatamente após a entrada (para ambos os lados), podendo zerar a posição quase de imediato em movimentos laterais.
4. **Falta de filtros** — sem exigir mínimas velas formadas, sem proteger contra spread inválido/negativo e sem impedir rompimentos "falsos" (pin de topo/fundo).

Segue o **código completo corrigido e comentado** (mantendo sua estrutura e constantes editáveis):

```cpp
#property strict
#include <Trade\Trade.mqh>
#include <stdlib.h>
#include <string.h>

// ================================================================
// PARÂMETROS DA ESTRATÉGIA (ajuste conforme o par / corretora)
// ================================================================
const double LOTE       = 0.01;   // tamanho padrão da posição
const double TP_PIP     = 10.0;   // Take Profit (em pips)
const double SL_PIP     = 20.0;   // Stop Loss inicial (em pips)
const double TRAIL_PIP  = 10.0;   // Trailing Stop (em pips)
const double GUARD_PIP  = 5.0;    // movimento mínimo p/ o trailing "engatar" (pips)
const double ROM_PIP    = 2.0;    // rompimento mínimo reconhecido (pips)
const double CORPO_PCT  = 0.12;   // vela deve desenvolver X% do ATR antes de sinalizar

CTrade trade;   // gerenciamento de ordens e posições

// ---------------------------------------------------------------------
// ESTADO GLOBAL (acompanha a sequência de velas abertas)
// ---------------------------------------------------------------------
ulong   gBarCorrente;         // índice da VELA ATUAL em formação
double  gAltaAnt, gBaixaAnt;  // máxima e mínima da ÚLTIMA vela COMPLETA
bool    gCompraEstaVela, gVendaEstaVela; // já tentou abrir qual lado NESTA vela?

// ---------------------------------------------------------------
// FUNÇÕES AUXILIARES
// ---------------------------------------------------------------

double PrecoNorm(double p) { return NormalizeDouble(p, _Digits); }

// Spread em pips (detecta spread inválido/negativo)
double GetSpreadPP()
{
    double asp = SymbolInfoDouble(Symbol(), SYMBOL_ASK);
    double bdp = SymbolInfoDouble(Symbol(), SYMBOL_BID);
    if (asp <= bdp) return -1.0;      // spread inválido (ask <= bid)
    return (asp - bdp) / _Point;      // devolve spread em pips
}

// ATR atual (assinatura corrigida: símbolo + timeframe + período)
double GetATR(int periodo = 14)
{
    return iATR(Symbol(), PERIOD_CURRENT, periodo);
}

// Confere volatilidade mínima (evita sinais em mercado parado)
bool VolatilidadeMinima(void)
{
    return GetATR() > 0.0001; // ~1 pip mínimo (ajuste por par)
}

// OHLC da ÚLTIMA vela totalmente formada (índice = bar anterior)
void ObterVelaAnterior(ulong idx,
                       double &open, double &close, double &high, double &low)
{
    if (idx < 0 || idx >= iBarIndexCurrent()) return; // barra ainda não existe/fechou corretamente
    iOpen(NULL, PERIOD_CURRENT, (int)idx, open);
    iClose(NULL, PERIOD_CURRENT, (int)idx, close);
    iHigh(NULL, PERIOD_CURRENT, (int)idx, high);
    iLow(NULL, PERIOD_CURRENT, (int)idx, low);
}

// Analisa rompimento e retorna: 0 = sem sinal, 1 = COMPRA, 2 = VENDA
int AnalisaRompimento(double hCur, double lCur, double cCur,
                      double hAnt, double lAnt)
{
    if (!VolatilidadeMinima()) return 0;

    // a vela atual precisa mostrar desenvolvimento antes de considerar rompimento
    double corpoParcial = MathMax(hCur - iOpen(NULL, PERIOD_CURRENT, 0),
                                  MathAbs(lCur - iOpen(NULL, PERIOD_CURRENT, 0)));
    if (corpoParcial < GetATR() * CORPO_PCT) return 0;

    double cabo = ROM_PIP * _Point;           // distância mínima de rompimento (pontos)
    double romCima   = hCur - hAnt;          // quanto a alta atual estourou a máxima anterior
    double romBaixo  = lAnt - lCur;          // quanto a baixa atual mergulhou abaixo da mínima anterior

    // COMPRAS: close rompe a máxima E fecha firme na zona rompida (evita "pin" de topo)
    if (romCima > cabo && (cCur - hAnt) > cabo * 0.6) return 1;

    // VENDAS: close rompe a mínima E fecha firme abaixo dela (evita "pin" de fundo)
    if (romBaixo > cabo && (lAnt - cCur) > cabo * 0.6) return 2;

    return 0;
}

// Impede ordens duplicadas do mesmo lado no mesmo símbolo
bool PodeAbrirOrdem(ORDER_TYPE tipo)
{
    for (int i = 0; i < OrdersTotal(); i++)
    {
        if (OrderSelect(i, SELECT_BY_POS | CHECK_NOTPOS))
        {
            if (OrderInteger(OrderType()) == (int)tipo && StringCompare(Symbol(), Symbol()) == 0)
                return false; // já existe ordem ativa do mesmo lado
        }
    }
    return true;
}

// Envia a ordem e CORRETPõe TP/SL exatos em relação ao preço de ENTRADA após o envio
bool EnviarOrdem(ORDER_TYPE tipo, double precoExecucao)
{
    MqlTradeRequest req;
    MqlTradeResult res;
    ZeroMemory(req); ZeroMemory(res);

    req.action      = TRADE_ACTION_DEAL;
    req.symbol      = Symbol();
    req.volume      = LOTE;
    req.type        = tipo;
    req.price       = PrecoNorm(precoExecucao);
    req.deviation   = 3;

    if (!trade.OrderSend(req, res))
    {
        Print("Falha ao enviar ordem: ", GetLastError());
        return false;
    }

    if (res.retcode == TRADE_SUCCEEDED)
    {
        double entrada = PositionGetDouble(POSITION_OPEN);
        double novoSL, novoTP;

        if (tipo == ORDER_TYPE_BUY)
        {
            novoSL = PrecoNorm(entrada - SL_PIP * _Point);
            novoTP = PrecoNorm(entrada + TP_PIP * _Point);
        }
        else
        {
            novoSL = PrecoNorm(entrada + SL_PIP * _Point);
            novoTP = PrecoNorm(entrada - TP_PIP * _Point);
        }

        trade.PositionModify(res.ticket, novoSL, novoTP);
        PrintFormat("Ordem %s aberta! Ticket: %u | TP: %.5f | SL: %.5f",
                    tipo == ORDER_TYPE_BUY ? "COMPRA" : "VENDA",
                    (uint)res.ticket, novoTP, novoSL);
        return true;
    }

    ImprimirMotivo(res.retcode, tipo == ORDER_TYPE_BUY ? "compra" : "venda");
    return false;
}

void ImprimirMotivo(int retCode, const string lado[])
{
    string msg;
    switch (retCode)
    {
        case TRADE_REJECTED:       msg = "Recusada pela corretora."; break;
        case TRADE_ALREADY_EXECUTED: msg = "Já executada (duplicada)."; break;
        default:                   msg = "Erro código: " + IntegerToString(retCode) + " - verifique corretora/simbólico.";
    }
    Print("Falha na ordem " + lado[0] + ": " + msg);
}

// ----------------------------------------------------------------------------
// ON_TICK — principal
// ----------------------------------------------------------------------------
void OnTick()
{
    if (!IsChartReady()) return;
    if (StringLen(Symbol()) < 3) return;

    const string sym = Symbol();
    double ask = SymbolInfoDouble(sym, SYMBOL_ASK);
    double bid = SymbolInfoDouble(sym, SYMBOL_BID);

    // Proteções básicas
    if (ask <= bid) return;                               // spread inválido
    if (GetSpreadPP() > 10.0) return;                     // espalhamento fora do limite (pips)

    double atr = GetATR();
    ulong cur = iBarIndexCurrent();

    // Só gera sinal após pelo menos 1 vela COMPLETA existir (bar anterior)
    if (cur < 2) return;                                  // Velas mínimas = 2

    // ===================== VELA ATUAL (em formação) ==========================
    double oCur, cCur, hCur, lCur;
    iOpen(NULL, PERIOD_CURRENT, 0, oCur);
    iClose(NULL, PERIOD_CURRENT, 0, cCur);
    iHigh(NULL, PERIOD_CURRENT, 0, hCur);
    iLow(NULL, PERIOD_CURRENT, 0, lCur);

    // ===================== VELA ANTERIOR (totalmente fechada) ===============
    double oAnt, cAnt, hAnt, lAnt;
    ObterVelaAnterior((ulong)(cur - 1), oAnt, cAnt, hAnt, lAnt);

    // ===================== ANÁLISE DE ROMPIMENTO ===========================
    int acao = AnalisaRompimento(hCur, lCur, cCur, hAnt, lAnt);
    if (acao == 0) return;                                // sem rompimento válido

    // Filtro extra: ignora velas que JÁ abrem fora do range anterior
    // (continuam tendência em vez de romper consolidação)
    if (acao == 1 && hCur > gAltaAnt + ROM_PIP) return;
    if (acao == 2 && lCur < gBaixaAnt - ROM_PIP)  return;

    // ============================== COMPRA =================================
    if (acao == 1)
    {
        if (gCompraEstaVela) return;                      // não tenta novamente nesta vela
        gCompraEstaVela = true;
        if (!PodeAbrirOrdem(ORDER_TYPE_BUY)) return;      // já tem posição deste lado?
        if (EnviarOrdem(ORDER_TYPE_BUY, ask))
            PrintFormat("[OK] COMPRA aberta: alta %.5f > máx. anterior %.5f (+%.5f pips)",
                        hCur, gAltaAnt, hCur - gAltaAnt);
        else
            Print("Falha ao abrir COMPRA: ");
    }

    // ============================== VENDA =================================
    else if (acao == 2)
    {
        if (gVendaEstaVela) return;
        gVendaEstaVela = true;
        if (!PodeAbrirOrdem(ORDER_TYPE_SELL)) return;
        if (EnviarOrdem(ORDER_TYPE_SELL, bid))
            PrintFormat("[OK] VENDA aberta: baixa %.5f < mín. anterior %.5f (-%.5f pips)",
                        lCur, gBaixaAnt, gBaixaAnt - lCur);
        else
            Print("Falha ao abrir VENDA: ");
    }

    // ===================== GESTÃO: TRAILING STOP NAS POSIÇÕES ===============
    ManageTrailingStop();
}

// ---------------------------------------------------------------------------
// TRAILING STOP SUBINDO (LONG) / DESCENDO (SHORT)
// ---------------------------------------------------------------------------
void ManageTrailingStop(void)
{
    for (int i = 0; i < PositionsTotal(); i++)
    {
        ulong ticket = PositionGetTicket(i);
        if (!PositionSelectByTicket(ticket)) continue;

        int tipo = (int)PositionGetInteger(POSITION_TYPE);
        if (tipo < 1) continue; // posição encerrada / inválida

        double sl = PositionGetDouble(POSITION_SL);
        double tp = PositionGetDouble(POSITION_TP);
        double aberto = PositionGetDouble(POSITION_OPEN);
        double ultimoPreco = (tipo == ORDER_TYPE_BUY) ? ask : bid;

        double T = TRAIL_PIP * _Point;

        // COMPRADA: chandelier stop SOBEM com o mercado
        if (tipo == ORDER_TYPE_BUY)
        {
            double cand = MathMax(sl, ultimoPreco - T);
            // Só desliza o stop após o preço sair da faixa de entrada (proteção inicial)
            if ((ultimoPreco - aberto) > GUARD_PIP * _Point && cand > sl)
            {
                double novoSL = PrecoNorm(cand);
                if (novoSL != sl)
                {
                    trade.PositionModify(ticket, novoSL, tp);
                    PrintFormat("Trailing (COMpra): SL ajustado %.5f (era %.5f) | %+.5f",
                                novoSL, sl, PositionGetDouble(POSITION_PROFIT));
                }
            }
        }
        // VENDEDORA: chandelier stop DESCE com o mercado
        else
        {
            double cand = MathMin(sl, ultimoPreco + T);
            if ((aberto - ultimoPreco) > GUARD_PIP * _Point && cand < sl)
            {
                double novoSL = PrecoNorm(cand);
                if (novoSL != sl)
                {
                    trade.PositionModify(ticket, novoSL, tp);
                    PrintFormat("Trailing (VENda): SL ajustado %.5f (era %.5f) | %+.5f",
                                novoSL, sl, PositionGetDouble(POSITION_PROFIT));
                }
            }
        }
    }
}
```

